/// Returns an upper bound on the difference between any two elements of the array.
/// In fact, this is simply max(a) – min(a).
///
/// # Panics
///
/// Panics if `a` has fewer than 2 elements.
pub fn MaxDifference(a: Vec<i64>) -> i64 {
    assert!(a.len() >= 2, "input array must have length at least 2");

    // Initialize both min and max with the first element.
    let mut min_val = a[0];
    let mut max_val = a[0];

    // Iterate over the remainder, updating min and max.
    for &x in &a[1..] {
        if x < min_val {
            min_val = x;
        }
        if x > max_val {
            max_val = x;
        }
    }

    // The largest difference between any two elements
    max_val - min_val
}

